([(
  $label := {"completed":"完成","success":"完成","noop":"無事可做","retry_success":"重試後完成","running":"執行中","waiting":"等待中","not_started":"未開始","pending":"未開始","out_of_window":"未到時段","stale":"待確認","skipped":"略過","at_risk":"趕不上截止","attention":"應跑未跑","overdue":"逾時","stuck":"卡住","missed":"漏跑","failed":"失敗","error":"失敗","blocked":"中止","ready":"就緒","ok":"正常","warn":"注意","fail":"未過","critical":"重大","warning":"注意","healthy":"正常","pending_maturity":"等待成熟","pass":"通過","collecting":"收集中","not_applicable_no_real_intents":"不適用（沒有真實下單）","owner_read_unavailable":"讀不到來源"};
  $hm := function($t) { $t ? $fromMillis($toMillis($t), '[H01]:[m01]', '+0800') : '' };
  $clock := function($r) {
    $r.display_status in ['not_started', 'out_of_window', 'waiting', 'overdue', 'at_risk', 'stuck']
      ? ($r.expected_by ? '截止 ' & $hm($r.expected_by) : '')
      : $r.display_status = 'running' ? $hm($r.started_at) & ' 起' : $hm($r.completed_at ? $r.completed_at : $r.started_at)
  };
  $merge(rows[active = true and display_position != null].{
    's_' & stage_id: display_status,
    'b_' & stage_id: 'f_' & display_status,
    'c_' & stage_id: 'c_' & display_status,
    't_' & stage_id: $trim($lookup($label, display_status) & ' ' & $clock($))
  })
)])

